<script setup lang="ts">import {useResearch} from '../stores/research';import {runStatus} from '../constants/enums';const research=useResearch()</script><template><label class="run-select">冻结检验<select aria-label="选择检验结果" :value="research.selected" @change="research.select(Number(($event.target as HTMLSelectElement).value))"><option v-for="r in research.runs" :value="r.id" :key="r.id">#{{r.id}} {{r.name}} · {{runStatus[r.status]}}</option></select></label></template>